  auto MAP_VALUES__ = MAP_VALUES ? _fbb.CreateVector<uint8_t>(*MAP_VALUES) : 0;
  auto PERCENTILE_LEVELS__ = PERCENTILE_LEVELS ? _fbb.CreateVector<float>(*PERCENTILE_LEVELS) : 0;
  auto PERCENTILE_VALUES__ = PERCENTILE_VALUES ? _fbb.CreateVector<double>(*PERCENTILE_VALUES) : 0;
  auto PAYLOAD_CID__ = PAYLOAD_CID ? _fbb.CreateString(PAYLOAD_CID) : 0;
