inline const SKT *GetSKT(const void *buf) {
  return ::flatbuffers::GetRoot<SKT>(buf);
}

inline const SKT *GetSizePrefixedSKT(const void *buf) {
  return ::flatbuffers::GetSizePrefixedRoot<SKT>(buf);
}

inline const char *SKTIdentifier() {
  return "$SKT";
}

inline bool SKTBufferHasIdentifier(const void *buf) {
  return ::flatbuffers::BufferHasIdentifier(
      buf, SKTIdentifier());
}

inline bool SizePrefixedSKTBufferHasIdentifier(const void *buf) {
  return ::flatbuffers::BufferHasIdentifier(
      buf, SKTIdentifier(), true);
}

template <bool B = false>
inline bool VerifySKTBuffer(
    ::flatbuffers::VerifierTemplate<B> &verifier) {
  return verifier.template VerifyBuffer<SKT>(SKTIdentifier());
}

template <bool B = false>
inline bool VerifySizePrefixedSKTBuffer(
    ::flatbuffers::VerifierTemplate<B> &verifier) {
  return verifier.template VerifySizePrefixedBuffer<SKT>(SKTIdentifier());
}

inline void FinishSKTBuffer(
    ::flatbuffers::FlatBufferBuilder &fbb,
    ::flatbuffers::Offset<SKT> root) {
  fbb.Finish(root, SKTIdentifier());
}

inline void FinishSizePrefixedSKTBuffer(
    ::flatbuffers::FlatBufferBuilder &fbb,
    ::flatbuffers::Offset<SKT> root) {
  fbb.FinishSizePrefixed(root, SKTIdentifier());
}

